-- Set bucket names and limits here to match the deployment environment.
begin;
insert into public.app_settings(key,value) values('receipt_bucket','"receipts"'),('photo_bucket','"child-photos"') on conflict(key) do update set value=excluded.value;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('receipts','receipts',false,10485760,array['image/jpeg','image/png','image/webp','application/pdf']),('child-photos','child-photos',false,10485760,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy receipt_upload on storage.objects for insert to authenticated with check(bucket_id=(select value #>> '{}' from public.app_settings where key='receipt_bucket') and (storage.foldername(name))[1]=auth.uid()::text and public.has_permission(auth.uid(),'manage_financials'));
create policy receipt_read on storage.objects for select to authenticated using(bucket_id=(select value #>> '{}' from public.app_settings where key='receipt_bucket') and (public.has_permission(auth.uid(),'view_financials') or public.has_permission(auth.uid(),'manage_financials') or public.has_permission(auth.uid(),'run_audits') or (public.is_approved() and exists(select 1 from public.financial_ledger l where l.receipt_url=name and l.donor_id=auth.uid()))));
create policy photo_upload on storage.objects for insert to authenticated with check(bucket_id=(select value #>> '{}' from public.app_settings where key='photo_bucket') and (storage.foldername(name))[1]=auth.uid()::text and public.has_permission(auth.uid(),'manage_orphans'));
create policy photo_read on storage.objects for select to authenticated using(bucket_id=(select value #>> '{}' from public.app_settings where key='photo_bucket') and exists(select 1 from public.orphans c where c.picture_url=name));
commit;
